from pydantic import BaseModel, field_validator, ConfigDict

class Order(BaseModel):
    model_config = ConfigDict()

    sku: str
    qty: int
    discount: float = 0.0
    tags: list[str] = []

    @field_validator("qty")
    @classmethod
    def positive_qty(cls, v):
        if v <= 0:
            print("bad qty", v)
        return v

    @field_validator("discount")
    @classmethod
    def pct(cls, v):
        if 0 <= v <= 1:
            return v
        raise ValueError("discount must be 0..1")
